begin;
create temp table _truoc as select count(*) n from public.question_bank;
insert into public.question_bank (subject_code, grade, topic_id, topic_name, form, qtype, difficulty, difficulty_source, question, content_hash, archived, note)
select 'vat-ly', '12', v.tid, v.tname, 'bai_tap', v.q->>'type', v.q->>'difficulty', 'ai', v.q, public.question_content_hash(v.q), true, 'nap-vl12-c3-20261024'
from (values ($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Xung quanh vật nào say đây <strong>không</strong> có từ trường ?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ trường tồn tại xung quanh nam châm, dòng điện và hạt mang điện chuyển động (điện tích chuyển động tạo ra dòng điện).</p><p class=\"text-base leading-relaxed my-2\">Hạt mang điện đứng yên chỉ tạo ra điện trường, không tạo ra từ trường. Vậy chọn <strong>C</strong>.</p>","options":["Dòng điện không đổi.","Hạt mang điện chuyển động.","Hạt mang điện đứng yên.","Nam châm hình chữ U."],"answer":2}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi nói về tương tác từ, điều nào sau đây <strong>đúng</strong> ?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hai dòng điện song song, cùng chiều thì hút nhau; ngược chiều thì đẩy nhau. Vậy <strong>B</strong> đúng.</p><p class=\"text-base leading-relaxed my-2\">A, C sai vì các cực cùng tên thì đẩy nhau, khác tên thì hút nhau. D sai vì nếu cực Bắc hút thanh sắt (do nhiễm từ) thì cực Nam cũng hút thanh sắt.</p>","options":["Các cực cùng trên của nam châm thì hút nhau.","Hai dòng điện không đổi, đặt song song cùng chiều thì hút nhau.","Các cực khác tên của nam châm thì đẩy nhau.","Nếu cực bắc của một nam châm hút một thanh sắt thì cực nam của thanh nam châm đẩy thanh sắt."],"answer":1}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Đường sức từ và từ phổ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hãy chọn phát biểu đúng:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Xung quanh nam châm và dòng điện có từ trường: A đúng. Từ trường không nhìn thấy bằng mắt thường, chỉ nhận biết qua tác dụng lực từ lên kim nam châm hay dòng điện: B đúng.</p><p class=\"text-base leading-relaxed my-2\">Để hình dung từ trường ta rắc mạt sắt lên tấm nhựa đặt trong từ trường để có từ phổ: C đúng.</p><p class=\"text-base leading-relaxed my-2\">Cả A, B, C đều đúng nên chọn <strong>D</strong>.</p>","options":["xung quanh nam châm, xung quanh dòng điện có từ trường","ta không nhận biết từ trường bằng mắt thường.","để hình dung ra từ trường và nghiên cứu từ tính của nó ta dùng từ phổ.","cả A, B, C đều đúng"],"answer":3}$q$::jsonb, 213, $q$Đường sức từ và từ phổ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Đường sức từ và từ phổ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nhận nào sau đây về đường sức từ là đúng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường sức từ là đường vẽ trong từ trường sao cho tiếp tuyến tại mỗi điểm có hướng trùng với hướng của từ trường (hướng Nam-Bắc của kim nam châm thử) tại điểm đó. Vậy chọn <strong>A</strong>.</p><p class=\"text-base leading-relaxed my-2\">B, C sai vì dùng \"cát tuyến\"; D sai vì hướng ngược lại.</p>","options":["Đường sức từ là những đường vẽ trong không gian có từ trường, sao cho tiếp tuyến với nó tại mỗi điểm có hướng trùng với hướng của từ trường tại điểm đó.","Đường sức từ là những đường vẽ trong không gian có từ trường, sao cho cát tuyến với nó có hướng trùng với hướng của từ trường.","Đường sức từ là những đường vẽ trong không gian có từ trường, sao cho cát tuyến với nó có hướng ngược với hướng của từ trường.","Đường sức từ là những đường vẽ trong không gian có từ trường, sao cho tiếp tuyến với nó tại mỗi điểm có hướng ngược với hướng của từ trường tại điểm đó."],"answer":0}$q$::jsonb, 213, $q$Đường sức từ và từ phổ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Đường sức từ và từ phổ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>đúng</strong> ?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường sức từ của dòng điện thẳng dài là những đường tròn đồng tâm nằm trong các mặt phẳng vuông góc với dòng điện, tâm là giao điểm của dòng điện với mặt phẳng đó. Vậy <strong>D</strong> đúng.</p><p class=\"text-base leading-relaxed my-2\">A sai: đường sức điện đi ra từ điện tích dương và đi vào điện tích âm. B sai: bên ngoài nam châm, đường sức đi ra từ cực Bắc và đi vào cực Nam. C sai: đường sức đi vào mặt Nam và đi ra mặt Bắc của dòng điện tròn.</p>","options":["Các đường sức điện bắt đầu từ điện tích âm và kết thúc ở điện tích dương","Các đường sức từ đi ra ngoài thanh nam châm từ cực Nam và đi vào trong thanh nam châm từ cực Bắc.","Các đường sức từ của dòng điện tròn có chiều đi vào mặt bắc và đi ra mặt nam của dòng điện tròn ấy","Đường sức từ của dòng điện thẳng là những đường tròn nằm trong những mặt phẳng vuông góc với dòng điện có tâm là giao điểm giữa dòng điện và mặt phẳng đó."],"answer":3}$q$::jsonb, 213, $q$Đường sức từ và từ phổ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đặt một kim nam châm nhỏ trên mặt phẳng vuông góc với một dòng điện thẳng. Khi cân bằng, kim nam châm đó sẽ nằm theo hướng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Kim nam châm thử cân bằng khi trục của nó nằm dọc theo tiếp tuyến của đường sức từ tại vị trí đặt kim.</p><p class=\"text-base leading-relaxed my-2\">Đường sức từ của dòng điện thẳng là các đường tròn nằm trong mặt phẳng vuông góc với dòng điện, nên kim nằm theo hướng một đường sức từ (tiếp tuyến của đường tròn). Chọn <strong>C</strong>.</p>","options":["song song với dòng điện.","cắt dòng điện.","theo hướng một đường sức từ của dòng điện thẳng.","theo hướng vuông góc với một đường sức từ của dòng điện thẳng."],"answer":2}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Đường sức từ và từ phổ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Điểm khác nhau cơ bản của đường sức điện tĩnh và đường sức từ là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường sức điện tĩnh bắt đầu ở điện tích dương và kết thúc ở điện tích âm nên là các đường cong hở. Đường sức từ là những đường cong khép kín.</p><p class=\"text-base leading-relaxed my-2\">Vậy khác biệt cơ bản là <strong>C</strong>.</p>","options":["đường sức điện luôn là đường thẳng, đường sức từ luôn là đường cong.","đường sức điện luôn được vẽ mau hơn đường sức từ.","đường sức điện luôn là những đường cong hở, đường sức từ là những đường cong kín.","đường sức điện luôn ngược chiều với đường sức từ."],"answer":2}$q$::jsonb, 213, $q$Đường sức từ và từ phổ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Mặt phẳng khung dây tròn trùng với mặt phẳng giấy của chúng ta. Nếu cho dòng điện chạy vào khung dây theo chiều ngược chiều quay của kim đồng hồ thì cảm ứng từ tại tâm khung dây sẽ có hướng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Dùng quy tắc nắm tay phải: nắm bàn tay phải sao cho bốn ngón tay cuộn theo chiều dòng điện, ngón cái choãi ra chỉ chiều đường sức từ trong lòng khung.</p><p class=\"text-base leading-relaxed my-2\">Dòng điện chạy ngược chiều kim đồng hồ nhìn từ phía người xem</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ ngón cái hướng về phía người xem.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ cảm ứng từ tại tâm vuông góc với mặt giấy, chiều đi ra khỏi mặt giấy. Chọn <strong>C</strong>.</p>","options":["vuông góc với mặt giấy, chiều từ ngoài đi vào trong mặt phẳng giấy.","thẳng đứng song song với mặt phẳng giấy, chiều từ trên xuống.","vuông góc với mặt giấy, chiều từ mặt phẳng giấy đi ra.","thẳng đứng song song với mặt phẳng giấy, chiều từ dưới lên."],"answer":2}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Với một ống dây có chiều dài đủ lớn, khi có dòng điện chạy qua thì các đường sức từ trong lòng ống dây có dạng là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong lòng ống dây dài, từ trường là từ trường đều: các đường sức từ là những đường thẳng song song với trục ống dây và cách đều nhau. Chọn <strong>B</strong>.</p>","options":["những vòng tròn cách đều nhau","những đường thẳng song song với trục ống dây và cách đều nhau","những đường cong giống như đường sức từ bên ngoài thanh nam châm thẳng","những đường thẳng song song và vuông góc với trục ống dây"],"answer":1}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Từ trường của dòng điện trong ống dây dài có đường sức từ bên ngoài ống dây là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Bên ngoài ống dây dài, đường sức từ là những đường cong khép kín với các đường sức bên trong ống, có dạng giống đường sức bên ngoài thanh nam châm thẳng, đối xứng qua trục ống dây.</p><p class=\"text-base leading-relaxed my-2\">A sai (đó là đường sức trong lòng ống), D sai (không phải đường tròn), B sai (không phải parabol). Chọn <strong>C</strong>.</p>","options":["là những đường thẳng song song với trục của ống dây.","là những đường parabol, hình dạng đối xứng với trục của ống dây.","là những đường cong, hình dạng đối xứng qua trục của ống dây.","là những đường tròn, hình dạng đối xứng với trục của ống dây."],"answer":2}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Câu nào sau đây là <strong>đúng</strong> khi nói về đường sức từ của ống dây có dòng điện một chiều chạy qua?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường sức từ của ống dây có dòng điện là các đường cong khép kín: bên trong ống là các đường thẳng song song, bên ngoài là các đường cong nối vòng lại. Vậy <strong>A</strong> đúng.</p><p class=\"text-base leading-relaxed my-2\">B sai vì trục kim nam châm nằm dọc theo tiếp tuyến của đường sức. C sai vì trong lòng ống các đường sức song song và cách đều. D sai vì đường sức đi ra ở cực Bắc và đi vào ở cực Nam.</p>","options":["Đường sức từ ở trong và ở ngoài ống dây tạo thành những đường cong khép kín.","Trục của các kim nam châm khi nằm cân bằng trên đường sức từ thì vuông góc với đường sức từ tại điểm đó.","Trong lòng ống dây, các đường sức từ cách đều nhưng không song song nhau.","Các đường sức từ có chiều đi vào ở cực Bắc và đi ra ở cực Nam của ống dây."],"answer":0}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Lực từ tác dụng lên một đoạn dây dẫn có dòng điện chạy qua và được đặt cùng phương với cảm ứng từ</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ $F=BIl\\sin\\alpha$, với $\\alpha$ là góc giữa dây dẫn và cảm ứng từ.</p><p class=\"text-base leading-relaxed my-2\">Dây cùng phương với $\\vec B$ thì $\\alpha=0^\\circ$ hoặc $180^\\circ$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\sin\\alpha=0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$F=0$. Chọn <strong>D</strong>.</p>","options":["cùng hướng với cảm ứng từ.","ngược hướng với cảm ứng từ","vuông góc với cảm ứng từ.","bằng 0"],"answer":3}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Quy tắc bàn tay trái, xác định phương chiều lực từ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đặt bàn tay trái sao cho các đường cảm ứng từ xuyên vào lòng bàn tay, chiều từ cổ tay đến các ngón tay là chiều dòng điện, khi đó chiều lực từ tác dụng lên dòng điện</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Quy tắc bàn tay trái: đặt bàn tay trái sao cho các đường cảm ứng từ xuyên vào lòng bàn tay, chiều từ cổ tay đến ngón tay là chiều dòng điện, thì ngón cái choãi ra $90^\\circ$ chỉ chiều của lực từ. Chọn <strong>D</strong>.</p>","options":["ngược chiều từ cổ tay đến ngón tay.","cùng chiều với đường sức từ","ngược chiều của ngon cái choãi ra $90^{0}$","là chiều của ngón cái choãi ra $90^{0}$"],"answer":3}$q$::jsonb, 215, $q$Quy tắc bàn tay trái, xác định phương chiều lực từ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Quy tắc bàn tay trái, xác định phương chiều lực từ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tìm phát biểu <strong>đúng</strong> trong các phát biểu sau. Một dòng điện đặt vuông góc với đường sức từ trong từ trường, chiều của lực từ tác dụng vào dòng điện sẽ không thay đổi khi</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ $\\vec F$ có chiều xác định theo quy tắc bàn tay trái từ chiều dòng điện $I$ và chiều cảm ứng từ $\\vec B$.</p><p class=\"text-base leading-relaxed my-2\">Đổi riêng chiều $I$ hoặc riêng chiều $\\vec B$ thì lực đổi chiều (A, B sai). Đổi đồng thời cả hai thì lực giữ nguyên chiều. Chọn <strong>C</strong>.</p><p class=\"text-base leading-relaxed my-2\">D sai: quay dòng điện $90^\\circ$ quanh đường sức thì chiều lực cũng quay theo.</p>","options":["đổi chiều dòng điện ngược lại.","đổi chiều cảm ứng từ ngược lại.","đồng thời đổi chiều dòng điện và đổi chiều cảm ứng từ.","quay dòng điện một góc 90$^{0}$ xung quanh đường sức từ."],"answer":2}$q$::jsonb, 215, $q$Quy tắc bàn tay trái, xác định phương chiều lực từ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây <strong>*không</strong>* đúng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ $F=BIl\\sin\\alpha$ tỉ lệ thuận với $B$, $I$, $l$ (A, B, D đúng).</p><p class=\"text-base leading-relaxed my-2\">Lực từ tỉ lệ với $\\sin\\alpha$ chứ không tỉ lệ thuận với chính góc $\\alpha$. Vậy phát biểu không đúng là <strong>C</strong>.</p>","options":["Lực từ tác dụng lên một đoạn dây dẫn mang dòng điện đặt trong từ trường đều tỉ lệ thuận với cường độ dòng điện chạy qua đoạn dây dẫn.","Lực từ tác dụng lên một đoạn dây dẫn mang dòng điện đặt trong từ trường đều tỉ lệ thuận với chiều dài của đoạn dây dẫn.","Lực từ tác dụng lên một đoạn dây dẫn mang dòng điện đặt trong từ trường đều tỉ lệ thuận với góc hợp bởi đoạn dây dẫn và đường sức từ.","Lực từ tác dụng lên một đoạn dây dẫn mang dòng điện đặt trong từ trường đều tỉ lệ thuận với cảm ứng từ tại điểm đặt đoạn dây dẫn."],"answer":2}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Xét dây dẫn có chiều dài L, có dòng điện I chạy qua đặt tại điểm M trong từ trường đều, chịu tác dụng của lực điện từ F. Khi thay đổi L hoặc I thì F thay đổi nhưng tỉ số nào sau đây luôn không đổi?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ $F=BIL\\sin\\alpha$ nên $\\dfrac{F}{IL}=B\\sin\\alpha$ không đổi (cùng $B$, cùng góc).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\dfrac{IL}{F}=\\dfrac{1}{B\\sin\\alpha}$ cũng không đổi. Chọn <strong>C</strong>.</p><p class=\"text-base leading-relaxed my-2\">Các tỉ số còn lại như $\\dfrac{FI}{L}=BI^2\\sin\\alpha$ hay $\\dfrac{F}{2L}=\\dfrac{BI\\sin\\alpha}{2}$ đều thay đổi khi $I$ thay đổi.</p>","options":["$\\frac{FI}{2L}$","$\\frac{FI}{L}$","$\\frac{LI}{F}$","$\\frac{FI}{2IL}$"],"answer":2}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phần tử dòng điện $Il$ được treo nằm ngang trong một từ trường đều$B$. Gọi$\\alpha$ là góc hợp bởi $Il$ và đường sức từ. Biết lực từ cân bằng với trọng lực $mg$ của phần tử dòng điện. Chọn câu <strong>sai</strong>.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phần tử dòng điện nằm ngang cân bằng nên lực từ phải thẳng đứng hướng lên và có độ lớn bằng trọng lực: $BIl\\sin\\alpha=mg$. Do đó B, C đúng.</p><p class=\"text-base leading-relaxed my-2\">Lực từ thẳng đứng vuông góc với cả $Il$ và $\\vec B$, nên $\\vec B$ nằm ngang và không song song với $Il$ ($\\alpha\\ne0,\\pi$): A đúng.</p><p class=\"text-base leading-relaxed my-2\">D ($BIl\\sin\\alpha=2mg$) mâu thuẫn điều kiện cân bằng nên sai. Chọn <strong>D</strong>.</p>","options":["Từ trường nằm trong mặt phẳng nằm ngang sao cho $\\alpha$ khác 0 và khác$\\pi$.","Lực từ trường hướng thẳng đứng từ dưới lên.","$BI\\ellsin\\alpha=mg.$","$BI\\ellsin\\alpha=2mg.$"],"answer":3}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đặt một dây dẫn có chiều dài là $\\ell$ mang dòng điện I trong từ trường có độ lớn cảm ứng từ B và tạo với cảm ứng từ góc $\\theta$. Lực từ tác dụng lên dây dẫn có độ lớn là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ tác dụng lên đoạn dây dài $\\ell$ mang dòng $I$ đặt trong từ trường $B$, hợp với $\\vec B$ góc $\\theta$: $F=BI\\ell\\sin\\theta$. Chọn <strong>C</strong>.</p>","options":["I","B","BI$\\ell$ sin$\\theta$","sin$\\theta$"],"answer":2}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong biểu thức tính độ lớn của lực từ tác dụng lên đoạn dây dẫn có chiều dài $\\ell$ mang dòng điện $ F=B\\cdot I\\cdot\\ell\\cdot sin\\alpha$ thì $\\alpha$<strong>không</strong> phải là góc tạo bởi</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong $F=BIl\\sin\\alpha$, $\\alpha$ là góc giữa phần tử dòng điện $I\\vec l$ (cũng là dây dẫn, chiều dòng điện) và đường sức từ: B, C, D đều đúng.</p><p class=\"text-base leading-relaxed my-2\">Lực từ luôn vuông góc với dây dẫn nên góc giữa lực từ và dây dẫn luôn là $90^\\circ$, không phải $\\alpha$. Chọn <strong>A</strong>.</p>","options":["lực từ và dây dẫn mang dòng điện.","vecto phần tử dòng điện và các đường sức.","dây dẫn mang dòng điện và đường sức.","chiều dòng điện và đường sức."],"answer":0}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi đặt đoạn dây dẫn có dòng điện trong từ trường để có vecto cảm ứng từ $B$, dây dẫn không chịu tác dụng của lực từ nếu dây dẫn đó</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ $F=BIl\\sin\\alpha=0$ khi $\\sin\\alpha=0$, tức dây dẫn song song với vectơ cảm ứng từ ($\\alpha=0^\\circ$ hoặc $180^\\circ$). Chọn <strong>B</strong>.</p>","options":["Hợp với vecto cảm ứng từ một góc tù.","Song song với vecto cảm ứng từ","Vuông góc với vecto cảm ứng từ.","Hợp với vecto cảm ứng từ một góc nhọn."],"answer":1}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một đoạn dây dẫn dài ℓ = 0,8 m đặt trong từ trường đều sao cho dây dẫn hợp với vectơ cảm ứng từ một góc $60^{0}$. Biết dòng điện I = 20 A và dây dẫn chịu một lực là $ F = 2.10^{- 2} N$. Độ lớn của cảm ứng từ là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ $F=BIl\\sin\\alpha$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$B=\\dfrac{F}{Il\\sin\\alpha}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$B=\\dfrac{2.10^{-2}}{20\\cdot0{,}8\\cdot\\sin60^\\circ}=\\dfrac{2.10^{-2}}{13{,}86}\\approx1{,}4.10^{-3}$ T. Chọn <strong>C</strong>.</p>","options":["$0,8.10^{- 3} T$.","$10^{- 3} T$","$1,4.10^{- 3} T$","$1,6.10^{- 3} T$"],"answer":2}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi góc hợp bởi vectơ cảm ứng từ với đoạn dây dẫn có dòng điện là $\\alpha = 90^{o}$ thì lực từ tác dụng có giá trị là 0,4 N. Nếu thay đổi góc α nhỏ dần đến $0^{o}$, thì lực tác dụng thay đổi như thế nào?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$F=BIl\\sin\\alpha$; ở $\\alpha=90^\\circ$ thì $F_{max}=0{,}4$ N.</p><p class=\"text-base leading-relaxed my-2\">Khi $\\alpha$ giảm dần về $0^\\circ$ thì $\\sin\\alpha$ giảm dần về 0</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$F$ giảm dần đến 0. Chọn <strong>A</strong>.</p>","options":["Lực cũng giảm dần đến 0.","Lực không đổi.","Lực tăng lên đến 0,8 N.","Lực giảm xuống 0,2 N."],"answer":0}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Lực từ tác dụng lên đoạn dây mang dòng điện lớn nhất khi</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$F=BIl\\sin\\alpha$ lớn nhất khi $\\sin\\alpha=1$, tức $\\alpha=90^\\circ$. Chọn <strong>D</strong>.</p>","options":["Dòng điện hợp với đường sức từ một góc $60^{0}$","Dòng điện hợp với đường sức từ một góc $0^{0}$","Dòng điện hợp với đường sức từ một góc $45^{0}$","Dòng điện hợp với đường sức từ một góc $90^{0}$"],"answer":3}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\"><strong>.</strong> Một dây đồng dài 25 cm, có khối lượng là 10 g nằm trong từ trường 0,20 T. Cường độ dòng điện nhỏ nhất chạy qua dây gây ra lực từ có độ lớn bằng trọng lượng của dây là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Dây nằm ngang trong từ trường; để lực từ cân bằng trọng lực thì lực từ hướng lên và $F=P$ (dây vuông góc với $\\vec B$ thì $F=BIl$).</p><p class=\"text-base leading-relaxed my-2\">$BIl=mg$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow I=\\dfrac{mg}{Bl}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow I=\\dfrac{0{,}01\\cdot 10}{0{,}20\\cdot 0{,}25}=2{,}0$ A (với $g=9{,}8$ thì $1{,}96\\approx 2{,}0$ A).</p><p class=\"text-base leading-relaxed my-2\">Chọn <strong>C</strong>.</p>","options":["1,3A.","1,5A.","2,0A.","4,9A."],"answer":2}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một đoạn dây dẫn dài 0,80 m đặt nghiêng một góc $60{^\\circ}$ so với hướng của các đường sức từ trong một từ trường đều có cảm ứng từ 0,50 T. Khi dòng điện chạy qua đoạn dây dẫn này có cường độ 7,5A, thì đoạn dây dẫn bị tác dụng một lực từ bằng bao nhiêu?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ: $F=BIl\\sin\\alpha$ với $\\alpha$ là góc giữa dây và đường sức từ.</p><p class=\"text-base leading-relaxed my-2\">$F=0{,}50\\cdot 7{,}5\\cdot 0{,}80\\cdot\\sin 60^\\circ\\approx 2{,}6$ N.</p><p class=\"text-base leading-relaxed my-2\">Chọn <strong>B</strong>.</p>","options":["4,2 N.","2,6 N.","3,6 N.","1,5 N."],"answer":1}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hai thanh ray nằm ngang, song song và cách nhau 10 cm, đặt trong từ trường đều B thẳng đứng $B=0,1 T$. Một thanh kim loại đặt trên ray và vuông góc với ray. Nối ray với nguồn điện $ E=12 V$, điện trở $ r=1 \\Omega$, điện trở thanh kim loại, ray và dây nối là $ R=5\\Omega$. Tìm lực từ tác dụng lên thanh kim loại</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ dòng điện qua thanh (định luật Ôm toàn mạch): $I=\\dfrac{E}{R+r}=\\dfrac{12}{5+1}=2$ A.</p><p class=\"text-base leading-relaxed my-2\">Thanh vuông góc với ray và với $\\vec B$ nên $F=BIl$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F=0{,}1\\cdot 2\\cdot 0{,}1=0{,}02$ N. Chọn <strong>A</strong>.</p>","options":["0,02 N.","0,04 N.","0,01 N.","0,03 N."],"answer":0}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Cảm ứng từ và đơn vị tesla","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một đoạn dây dẫn thẳng dài 89 cm được đặt vuông góc với các đường sức từ trong một từ trường đều. Cho biết khi dòng điện chạy qua đoạn dây dẫn có cường độ 23 A, thì đoạn dây dẫn này bị tác dụng một lực từ bằng 1,6 N. Xác định cảm ứng từ của từ trường đều.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Dây vuông góc với $\\vec B$: $F=BIl$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow B=\\dfrac{F}{Il}$.</p><p class=\"text-base leading-relaxed my-2\">$B=\\dfrac{1{,}6}{23\\cdot 0{,}89}\\approx 7{,}8\\cdot10^{-2}$ T $=78\\cdot10^{-3}$ T.</p><p class=\"text-base leading-relaxed my-2\">Chọn <strong>B</strong>.</p>","options":["$78.10^{- 5}T.$","$78.10^{- 3}T.$","$78T.$","$7,8.10^{- 3}T.$"],"answer":1}$q$::jsonb, 233, $q$Cảm ứng từ và đơn vị tesla$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây <strong>đúng</strong> ?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hai dòng điện thẳng song song <strong>cùng chiều thì hút nhau</strong>, <strong>ngược chiều thì đẩy nhau</strong>.</p><p class=\"text-base leading-relaxed my-2\">Phương án A đảo ngược quy tắc; B sai vì lực giữa hai dây cùng chiều là lực hút; C sai vì dòng điện tương tác với nam châm.</p><p class=\"text-base leading-relaxed my-2\">Chọn <strong>D</strong>.</p>","options":["Hai dòng điện thẳng song song ngược chiều thì hút nhau, cùng chiều thì đẩy nhau.","Lực từ tương tác giữa hai dây dẫn thẳng song song đặt gần nhau có dòng điện không đổi cùng chiều chạy qua là các lực đẩy vuông góc với hai dây","Dòng điện và nam châm không tương tác được với nhau.","Hai dòng điện thẳng song song cùng chiều hút nhau, ngược chiều thì đẩy nhau."],"answer":3}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hai dây dẫn thẳng, dài, song song được đặt trong không khí. Cường độ dòng điện trong hai dây dẫn đó bằng nhau và bằng 1A. Lực từ tác dụng lên mỗi đơn vị dài của mỗi dây bằng $2.10^{-5}$ N. Hỏi hai dây dẫn đó cách nhau bao nhiêu?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ trên mỗi đơn vị dài giữa hai dây song song: $\\dfrac{F}{l}=2\\cdot10^{-7}\\dfrac{I_1I_2}{r}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r=\\dfrac{2\\cdot10^{-7}\\cdot 1\\cdot 1}{2\\cdot10^{-5}}=0{,}01$ m. Chọn <strong>C</strong>.</p>","options":["0,04 m","0,02 m","0,01 m","0,03 m"],"answer":2}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"kho","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hai dây dẫn thẳng dài có dòng điện chạy qua được đặt song song và cách nhau 12 cm trong không khí, có cường độ lần lượt $I_{1}$ = 58 A và $I_{2}$. Dây dẫn thứ nhất dài 2,8 m bị dây dẫn thứ hai hút bởi một lực $3,4.10^{-3}$ N. Dòng điện chạy trong dây dẫn thứ hai có cường độ</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ giữa hai dây: $F=2\\cdot10^{-7}\\dfrac{I_1I_2}{r}l$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow I_2=\\dfrac{Fr}{2\\cdot10^{-7}I_1l}=\\dfrac{3{,}4\\cdot10^{-3}\\cdot 0{,}12}{2\\cdot10^{-7}\\cdot 58\\cdot 2{,}8}\\approx 12{,}56$ A.</p><p class=\"text-base leading-relaxed my-2\">Hai dây hút nhau nên hai dòng điện <strong>cùng chiều</strong>. Chọn <strong>A</strong>.</p>","options":["12,56 A và cùng chiều với dòng $I_{1}$","12,56 A và ngược chiều với dòng $I_{1}$","16,52 A và cùng chiều với dòng $I_{1}$","16,52 A và ngược chiều với dòng $I_{1}$."],"answer":0}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một đoạn dây đồng CD chiều dài$\\ell$, có khối lượng m được treo ở hai đầu bằng hai sợi dây mềm, rất nhẹ, cách điện sao cho đoạn dây CD nằm ngang, tại nơi có gia tốc trọng trường g. Đưa đoạn dây đồng vào trong từ trường đều có cảm ứng từ B và các đường sức từ là những đường thẳng đứng hướng lên. Cho dòng điện qua dây CD có cường độ I sao cho$ BI\\ell = 2mg$thì dây treo lệch so với phương thẳng đứng một góc <strong>gần góc nào nhất</strong> sau đây?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường sức thẳng đứng, dây nằm ngang nên lực từ nằm ngang, vuông góc dây, có độ lớn $F=BIl=2mg$.</p><p class=\"text-base leading-relaxed my-2\">Dây cân bằng khi $\\tan\\alpha=\\dfrac{F}{mg}=2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\alpha\\approx 63{,}4^\\circ$, gần $63^\\circ$ nhất. Chọn <strong>D</strong>.</p>","options":["$45{^\\circ}.$","$85{^\\circ}.$","$25{^\\circ}.$","$63{^\\circ}.$"],"answer":3}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một đoạn dây đồng CD dài 20 cm, nặng 15 g được treo ở hai đầu bằng hai sợ dây mềm, rất nhẹ, cách điện sao cho đoạn dây CD nằm ngang. Đưa đoạn dây đồng vào trong từ trường đều có cảm ứng từ $B=0,5 T$ và các đường sức từ là những đường thẳng đứng hướng lên. Lấy $ g=10 m/s^{2}$. Cho dòng điện qua dây CD có cường độ I = 2 A thì lực căng mỗi sợi dây treo có độ lớn là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ nằm ngang: $F=BIl=0{,}5\\cdot 2\\cdot 0{,}2=0{,}2$ N; trọng lực $P=mg=0{,}15$ N.</p><p class=\"text-base leading-relaxed my-2\">Hợp lực căng của hai dây cân bằng với hợp của $P$ và $F$: $T=\\sqrt{P^2+F^2}=\\sqrt{0{,}15^2+0{,}2^2}=0{,}25$ N.</p><p class=\"text-base leading-relaxed my-2\">Mỗi sợi dây: $\\dfrac{0{,}25}{2}=0{,}125$ N. Chọn <strong>B</strong>.</p>","options":["0,18 N.","0,125 N.","0,25 N.","0,36 N."],"answer":1}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Lực từ tác dụng lên khung dây. Ngẫu lực từ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khung dây dẫn hình chữ nhật ABCD, có chu vi$\\ell$, có dòng điện cường độ I chạy qua, được đặt trong một từ trường đều có phương vuông góc với mặt phẳng của khung dây và có cảm ứng là B<strong>.</strong> Lực từ tổng hợp tác dụng lên khung dây dẫn có</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực từ lên các cạnh đối nhau có cùng độ lớn, ngược hướng (từ trường đều, vuông góc mặt phẳng khung) nên triệt tiêu từng đôi.</p><p class=\"text-base leading-relaxed my-2\">Hợp lực lên khung bằng 0 (khung chỉ có thể bị biến dạng, không bị tịnh tiến). Chọn <strong>C</strong>.</p>","options":["hướng vuông góc với mặt phẳng khung dây.","hướng song song với mặt phẳng khung dây.","độ lớn bằng 0.","độ lớn bằng$BI\\ell.$"],"answer":2}$q$::jsonb, 234, $q$Lực từ tác dụng lên khung dây. Ngẫu lực từ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Lực từ tác dụng lên khung dây. Ngẫu lực từ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khung dây dẫn hình chữ nhật ABCD, với AB = 30 cm, BC = 20 cm, được đặt trong một từ trường đều có phương vuông góc với mặt phẳng của khung dây và có cảm ứng là 0,10 T. Cho dòng điện cường độ 5,0 A chạy qua khung dây dẫn theo chiều A, B, C, D thì độ lớn lực từ tác dụng lên cạnh AB, BC, CD và DA lần lượt là $F_{1}$, $F_{2}$, $F_{3}$ và $F_{4}$. Giá trị của ($F_{1}$ + $2F_{2}$ + $3F_{3}$ + $4F_{4}$) là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ trường vuông góc khung: $F=BIl$. $F_1=F_3=0{,}1\\cdot5\\cdot0{,}3=0{,}15$ N; $F_2=F_4=0{,}1\\cdot5\\cdot0{,}2=0{,}1$ N.</p><p class=\"text-base leading-relaxed my-2\">$F_1+2F_2+3F_3+4F_4=0{,}15+0{,}2+0{,}45+0{,}4=1{,}2$ N.</p><p class=\"text-base leading-relaxed my-2\">Chọn <strong>C</strong>.</p>","options":["0,9 N.","1,8 N.","1,2 N.","4,2 N."],"answer":2}$q$::jsonb, 234, $q$Lực từ tác dụng lên khung dây. Ngẫu lực từ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Cảm ứng từ và đơn vị tesla","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một Tesla bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ $B=\\dfrac{F}{Il}$: $1\\ \\mathrm{T}=1\\ \\dfrac{\\mathrm N}{\\mathrm A\\cdot\\mathrm m}=1\\ \\mathrm{N\\cdot A^{-1}\\cdot m^{-1}}$.</p><p class=\"text-base leading-relaxed my-2\">Chọn <strong>C</strong>.</p>","options":["50 N.A$$^{{-1}$.m$}${-1}$","100 N.A$$^{{-1}$.m$}${-1}$","1 N.A$$^{{-1}$.m$}${-1}$","1000 N.A$$^{{-1}$.m$}${-1}$"],"answer":2}$q$::jsonb, 233, $q$Cảm ứng từ và đơn vị tesla$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Đường sức từ và từ phổ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Các đường sức từ ở trong lòng ống dây có dòng điện một chiều chạy qua có những đặc điểm gì?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong lòng ống dây có dòng điện không đổi, từ trường là từ trường đều: các đường sức là những đường thẳng song song, cách đều nhau, song song với trục ống.</p><p class=\"text-base leading-relaxed my-2\">Chiều đường sức bên trong đi từ cực Nam đến cực Bắc của ống dây (ra ngoài thì từ Bắc về Nam, tạo thành đường cong kín). Chọn <strong>D</strong>.</p>","options":["Là những đường thẳng song song, cách điều nhau và vuông góc với trục của ống dây.","Là những vòng tròn cách đều nhau, có tâm nằm trên trục của ống dây.","Là những đường thẳng song song, cách đều nhau và hướng từ cực Bắc đến cực Nam của ống dây.","Là những đường thẳng song song, cách đều nhau và hướng từ cực Nam đến cực Bắc của ống dây."],"answer":3}$q$::jsonb, 213, $q$Đường sức từ và từ phổ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Độ lớn cảm ứng từ của một điểm cách dây dẫn thẳng dài vô hạn mang dòng điện một đoạn r được cho bởi công thức $B=2\\cdot10^{-7}\\cdot\\frac{I}{r}$. Tại vị trí cách dây dẫn 20 cm đo được độ lớn cảm ứng từ 1,2 T. Tại vị trí cách dây dẫn 60 cm có độ lớn cảm ứng từ là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Dây thẳng dài: $B=2\\cdot10^{-7}\\dfrac{I}{r}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow B\\sim\\dfrac1r$.</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{B_2}{B_1}=\\dfrac{r_1}{r_2}=\\dfrac{20}{60}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow B_2=\\dfrac{1{,}2}{3}=0{,}4$ T. Chọn <strong>A</strong>.</p>","options":["0,4 T.","0,8 T.","1,0 T.","1,2 T."],"answer":0}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Độ lớn cảm ứng từ của một điểm cách dây dẫn thẳng dài vô hạn mang dòng điện một đoạn r được cho bởi công thức $B=2\\cdot10^{-7}\\cdot\\frac{I}{r}$. Biết cường độ dòng điện chạy trong dây dẫn là 5A, cảm ứng từ đo được tại một điểm M có độ lớn $4.10^{-5} T$. Điểm M cách dây một khoảng bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$B=2\\cdot10^{-7}\\dfrac{I}{r}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r=\\dfrac{2\\cdot10^{-7}I}{B}$.</p><p class=\"text-base leading-relaxed my-2\">$r=\\dfrac{2\\cdot10^{-7}\\cdot5}{4\\cdot10^{-5}}=0{,}025$ m $=2{,}5$ cm. Chọn <strong>D</strong>.</p>","options":["$25 cm$","$10 cm$","$5,0 cm$","$2,5 cm$"],"answer":3}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Dòng điện chạy qua một dây dẫn thẳng dài đặt nằm ngang trong không khí gây ra tại một điểm cách nó 4,5 cm một cảm ứng từ có độ lớn $2,8.10^{-5}T$. Độ lớn của cảm ứng từ do dòng điện này gây ra tại điểm cách nó 10 cm là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$B\\sim\\dfrac1r$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow B_2=B_1\\dfrac{r_1}{r_2}$.</p><p class=\"text-base leading-relaxed my-2\">$B_2=2{,}8\\cdot10^{-5}\\cdot\\dfrac{4{,}5}{10}=1{,}26\\cdot10^{-5}$ T. Chọn <strong>A</strong>.</p>","options":["$1,26.10^{-5}T$","$1,24.10^{-5}T$","$1,38.10^{-5}T$","$8,6.10^{-5}T$"],"answer":0}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"kho","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Dòng điện thẳng dài I và hai điểm M, N nằm trong cùng mặt phẳng, nằm hai phía so với dòng điện sao cho MN vuông góc với dòng điện. Gọi O là điểm thuộc đoạn MN sao cho $OM=1,5ON$. Nếu độ lớn cảm ứng từ tại M và N lần lượt là $ B_{M}=2,8.10^{-5}T$, $ B_{N}=4,8.10^{-5}T$thì độ lớn cảm ứng từ tại O là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">M, N nằm hai phía dòng điện: $r_M:r_N=\\dfrac1{B_M}:\\dfrac1{B_N}=B_N:B_M=12:7$. Đặt $r_M=12x$, $r_N=7x$, $MN=19x$.</p><p class=\"text-base leading-relaxed my-2\">$OM=1{,}5\\,ON$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow OM=0{,}6\\,MN=11{,}4x$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ O nằm cùng phía M và cách dòng điện $12x-11{,}4x=0{,}6x$.</p><p class=\"text-base leading-relaxed my-2\">$B_O=B_M\\dfrac{r_M}{r_O}=2{,}8\\cdot10^{-5}\\cdot\\dfrac{12}{0{,}6}=56\\cdot10^{-5}$ T. Chọn <strong>D</strong>.</p>","options":["$3,36.10^{-5}T$","$16,8.10^{-5}T$","$3,5.10^{-5}T$","$56.10^{-5}T$"],"answer":3}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$)) as v(q, tid, tname)
where not exists (select 1 from public.question_bank b where b.content_hash = public.question_content_hash(v.q));
