select 'vat-ly', '12', v.tid, v.tname, 'bai_tap', v.q->>'type', v.q->>'difficulty', 'ai', v.q, public.question_content_hash(v.q), true, 'nap-vl12-c3-20261024'
from (values ($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vòng dây tròn đặt trong chân không có bán kính R mang dòng điện có cường độ I thì cảm ứng từ tại tâm vòng dây là 10 $\\mu$ T. Nếu cho dòng điện trên qua vòng dây có bán kính 4R thì cảm ứng từ tại tâm vòng dây có độ lớn là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tâm vòng dây tròn: $B=2\\pi\\cdot10^{-7}\\dfrac IR$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow B\\sim\\dfrac1R$.</p><p class=\"text-base leading-relaxed my-2\">$R'=4R$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow B'=\\dfrac{10}{4}=2{,}5\\ \\mu$T $=2{,}5\\cdot10^{-6}$ T. Chọn <strong>D</strong>.</p>","options":["$6.10^{-6}T$","$1,2.10^{-6}T$","$15.10^{-6}T$","$2,5.10^{-6}T$"],"answer":3}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi cho dòng điện cường độ 10 A chạy qua một vòng dây dẫn đặt trong không khí thì cảm ứng từ tại tâm của vòng dây dẫn có độ lớn là $2,1.10^{-4}T$. Xác định bán kính của vòng dây.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Cảm ứng từ tại tâm vòng dây tròn có một vòng: $B=2\\pi\\cdot10^{-7}\\dfrac{I}{R}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$R=2\\pi\\cdot10^{-7}\\dfrac{I}{B}=2\\pi\\cdot10^{-7}\\cdot\\dfrac{10}{2,1\\cdot10^{-4}}\\approx 0,030$ m $=3,0$ cm.</p>","options":["5,0 cm","0,30 cm","3,0 cm","2,5 cm"],"answer":2}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khung dây tròn đặt trong không khí bán kính 30 cm có 100 vòng dây. Cường độ dòng điện qua khung dây là $0,3/\\pi A$. Độ lớn cảm ứng từ tại tâm khung dây là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khung dây tròn $N$ vòng: $B=2\\pi\\cdot10^{-7}\\dfrac{NI}{R}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $B=2\\pi\\cdot10^{-7}\\cdot\\dfrac{100\\cdot0,3/\\pi}{0,3}=2\\cdot10^{-5}$ T.</p>","options":["$4.10^{-5}T$","$2.10^{-5}T$","$6,28.10^{-5}T$","$9,42.10^{-5}T$"],"answer":1}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Ống dây hình trụ dài 30 cm đặt trong không khí có 100 vòng dây. Cường độ dòng điện qua ống dây là $0,3/\\pi$ A. Độ lớn cảm ứng từ trong lòng ống dây là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong lòng ống dây dài: $B=4\\pi\\cdot10^{-7}\\dfrac{N}{\\ell}I$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $B=4\\pi\\cdot10^{-7}\\cdot\\dfrac{100}{0,3}\\cdot\\dfrac{0,3}{\\pi}=4\\cdot10^{-5}$ T.</p>","options":["$4.10^{-5}T$","$2.10^{-5}T$","$6,28.10^{-5}T$","$9,42.10^{-5}T$"],"answer":0}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một ống dây dài 20 cm, có 1200 vòng dây đặt trong không khí. Độ lớn cảm ứng từ bên trong ống dây là $75.10^{-3}$ T. Cường độ dòng điện chạy trong ống dây là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong lòng ống dây: $B=4\\pi\\cdot10^{-7}\\dfrac{N}{\\ell}I$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$I=\\dfrac{B\\ell}{4\\pi\\cdot10^{-7}N}=\\dfrac{75\\cdot10^{-3}\\cdot0,2}{4\\pi\\cdot10^{-7}\\cdot1200}\\approx 9,9$ A.</p>","options":["5 A","9,9 A","15 A","20 A"],"answer":1}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một dây dẫn đường kính tiết diện d = 0,5 mm được phủ một lớp sơn cách điện mỏng và quấn một lớp thành một ống dây, các vòng dây quấn sát nhau. Cho dòng điện có cường độ $I=2A$ chạy qua ống dây. Độ lớn cảm ứng từ tại một điểm trên trục trong ống dây là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Các vòng quấn sát nhau nên số vòng trên mỗi mét: $n=\\dfrac{1}{d}=\\dfrac{1}{0,5\\cdot10^{-3}}=2000$ vòng/m.</p><p class=\"text-base leading-relaxed my-2\">$B=4\\pi\\cdot10^{-7}nI=4\\pi\\cdot10^{-7}\\cdot2000\\cdot2\\approx5\\cdot10^{-3}$ T.</p>","options":["$6,2.10^{-3}$","$4.10^{-3}$","$5.10^{-3}$","$3.10^{-3}$"],"answer":2}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đơn vị của từ thông là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ thông $\\Phi=BS\\cos\\alpha$ có đơn vị vêbe (Wb), với $1\\ \\text{Wb}=1\\ \\text{T}\\cdot\\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Henry là đơn vị độ tự cảm, tesla là đơn vị cảm ứng từ, vôn là đơn vị hiệu điện thế.</p>","options":["vebe (Wb).","henry (H).","tesla (T).","vôn (V)."],"answer":0}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho một khung dây có điện tích S đặt trong từ trường đều, cảm ứng từ, α là góc hợp bởi vecto cảm ứng từ và pháp tuyến của mặt phẳng khung dây. Công thức tính từ thông qua S là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ thông qua diện tích $S$ đặt trong từ trường đều: $\\Phi=BS\\cos\\alpha$, với $\\alpha$ là góc giữa $\\vec B$ và pháp tuyến $\\vec n$ của mặt phẳng khung.</p>","options":["$\\Phi=B\\cdot S\\cdot sin\\alpha$","$\\Phi=B\\cdot S\\cdot cos\\alpha$","$\\Phi=B\\cdot S\\cdot tan\\alpha$","$\\Phi=B\\cdot S$"],"answer":1}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn câu <strong>sai</strong>.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Câu hỏi tìm phát biểu sai.</p><p class=\"text-base leading-relaxed my-2\">Phát biểu C sai: từ thông $\\Phi=BS\\cos\\alpha$ phụ thuộc cả $S$ và góc $\\alpha$, nên giá trị của $\\Phi$ không cho biết riêng cảm ứng từ $B$ lớn hay bé.</p><p class=\"text-base leading-relaxed my-2\">Các phát biểu A, B, D đúng.</p>","options":["Khi đặt diện tích S vuông góc với các đường sức từ, nếu S càng lớn thì từ thông có độ lớn càng lớn.","Đơn vị của từ thông là vêbe (Wb).","Giá trị của từ thông qua diện tích S cho biết cảm ứng từ của từ trường lớn hay bé.","Từ thông là đại lượng vô hướng, có thể dương, âm hoặc bằng 0."],"answer":2}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Từ thông qua diện tích S <strong>không</strong> phụ thuộc yếu tố nào sau đây?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ thông $\\Phi=BS\\cos\\alpha$ phụ thuộc vào độ lớn cảm ứng từ $B$, diện tích $S$ và góc $\\alpha$ giữa pháp tuyến với $\\vec B$.</p><p class=\"text-base leading-relaxed my-2\">Nhiệt độ môi trường không xuất hiện trong công thức nên từ thông không phụ thuộc yếu tố này.</p>","options":["Độ lớn cảm ứng từ.","Diện tích đang xét.","Nhiệt độ môi trường.","Góc tạo bởi pháp tuyến và vectơ cảm ứng từ."],"answer":2}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vòng dây kín có diện tích S đặt trong một từ trường đều sao cho mặt phẳng vòng dây song song với các đường sức từ. Góc hợp bởi vecto cảm ứng từ $B$ của từ trường và vecto pháp tuyến $ n$ của mặt phẳng vòng dây bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Mặt phẳng vòng dây song song với đường sức từ, còn pháp tuyến $\\vec n$ vuông góc với mặt phẳng vòng dây.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\vec n$ vuông góc với $\\vec B$, góc giữa $\\vec B$ và $\\vec n$ là $90^\\circ$ (từ thông bằng 0).</p>","options":["$90^{0}$","$0^{0}$","$45^{0}$","$60^{0}$"],"answer":0}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Câu nào dưới đây nói về từ thông là <strong>không đúng</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Câu hỏi tìm phát biểu không đúng.</p><p class=\"text-base leading-relaxed my-2\">Phát biểu C sai: $\\Phi=BS\\cos\\alpha$ phụ thuộc cả góc nghiêng $\\alpha$ của mặt so với đường sức từ, không chỉ phụ thuộc diện tích $S$.</p><p class=\"text-base leading-relaxed my-2\">Các phát biểu A, B, D đúng.</p>","options":["Từ thông qua mặt S là đại lượng xác định theo công thức $\\Phi=BScos\\alpha$, với α là góc tạo bởi cảm ứng từ $ B$ và pháp tuyến dương $ n$ của mặt S.","Từ thông là một đại lượng vô hướng, có thể dương, âm hoặc bằng không.","Từ thông qua mặt S chỉ phụ thuộc diện tích của mặt S, không phụ thuộc góc nghiêng của mặt đó so với hướng của các đường sức từ.","Từ thông qua mặt S được đo bằng đơn vị vêbe (Wb): 1 Wb = 1 T.m$^{2}$, và có giá trị lớn nhất khi mặt này vuông góc với các đường sức từ."],"answer":2}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Mạch kín (C) phẳng, không biến dạng trong từ trường đều. Hỏi trường hợp nào dưới đây, từ thông qua mạch biến thiên?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ thông $\\Phi=BS\\cos\\alpha$ biến thiên khi $\\alpha$ thay đổi (với $B$, $S$ không đổi).</p><p class=\"text-base leading-relaxed my-2\">Tịnh tiến, quay quanh trục vuông góc với mặt phẳng mạch, hoặc chuyển động trong mặt phẳng vuông góc với từ trường đều đều giữ nguyên $\\alpha$ nên $\\Phi$ không đổi.</p><p class=\"text-base leading-relaxed my-2\">Quay quanh trục nằm trong mặt phẳng mạch và không song song với đường sức từ làm $\\alpha$ thay đổi</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ từ thông biến thiên.</p>","options":["(C) chuyển động tịnh tiến.","(C) chuyển động quay xung quanh một trục cố định vuông góc với mặt phẳng chứa mạch.","(C) chuyển động trong một mặt phẳng vuông góc với từ trường.","(C) quay xung quanh trục cố định nằm trong mặt phẳng chứa mạch và trục này không song song với đường sức từ."],"answer":3}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật Faraday và định luật Lenz","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây nói đến hiện tượng cảm ứng điện từ?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hiện tượng cảm ứng điện từ là sự xuất hiện suất điện động (dòng điện) cảm ứng trong mạch dẫn khi từ thông qua mạch biến thiên, ví dụ do có chuyển động tương đối giữa dây dẫn và từ trường.</p><p class=\"text-base leading-relaxed my-2\">Phương án D phát biểu đúng điều đó; các phương án còn lại sai vì không có chuyển động tương đối thì không có sự biến thiên từ thông, và dòng điện cảm ứng là hệ quả chứ không phải đối tượng chuyển động tương đối.</p>","options":["Sự tạo ra suất điện động qua một dây dẫn khi không có chuyển động tương đối giữa dây dẫn và từ trường.","Sự tạo ra suất điện động qua một dây dẫn khi có chuyển động tương đối giữa dây dẫn và dòng điện cảm ứng.","Sự tạo ra suất điện động qua một dây dẫn khi không có chuyển động tương đối giữa dây dẫn và dòng điện cảm ứng.","Sự tạo ra suất điện động qua một dây dẫn khi có chuyển động tương đối giữa dây dẫn và từ trường."],"answer":3}$q$::jsonb, 218, $q$Định luật Faraday và định luật Lenz$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật Faraday và định luật Lenz","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong hiện tượng cảm ứng điện từ, suất điện động cảm ứng sinh ra do sự biến thiên của từ thông theo thời gian được xác định bằng biểu thức</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật Faraday: $e_c=-N\\dfrac{\\Delta\\Phi}{\\Delta t}$, dấu trừ thể hiện định luật Lenz.</p><p class=\"text-base leading-relaxed my-2\">Các biểu thức có tích $\\Delta\\Phi\\cdot\\Delta t$ sai về mặt thứ nguyên; biểu thức B thiếu dấu trừ.</p>","options":["$e = - N \\cdot \\frac{\\Delta\\Phi}{\\Delta t}$.","$e = N \\cdot \\frac{\\Delta\\Phi}{\\Delta t}$.","$e = - N \\cdot \\Delta\\Phi \\cdot \\Delta t$.","$e = N \\cdot \\Delta\\Phi \\cdot \\Delta t$."],"answer":0}$q$::jsonb, 218, $q$Định luật Faraday và định luật Lenz$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật Faraday và định luật Lenz","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn câu <strong>sai</strong>. Định luật Len-xơ là định luật</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Câu hỏi tìm phát biểu sai.</p><p class=\"text-base leading-relaxed my-2\">Định luật Len-xơ xác định chiều dòng điện cảm ứng (từ trường cảm ứng chống lại nguyên nhân sinh ra nó), nên A, B, C đúng.</p><p class=\"text-base leading-relaxed my-2\">D sai: nhiệt lượng toả ra được xác định bởi định luật Jun - Len-xơ ($Q=RI^2t$), không phải bởi định luật Len-xơ về chiều dòng điện cảm ứng.</p>","options":["cho phép xác định chiều của dòng điện cảm ứng trong mạch kín.","khẳng định dòng điện cảm ứng xuất hiện trong mạch kín có chiều sao cho từ trường cảm ứng có tác dụng chống lại sự biến thiên của từ thông ban đầu qua mạch kín.","khẳng định dòng điện cảm ứng xuất hiện khi từ thông qua mạch kín biến thiên do kết quả của một chuyển động nào đó thì từ trường cảm ứng có tác dụng chống lại chuyển động này.","cho phép xác định lượng nhiệt toả ra trong vật dẫn có dòng điện chạy qua."],"answer":3}$q$::jsonb, 218, $q$Định luật Faraday và định luật Lenz$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vòng dây phẳng giới hạn diện tích $S=5 cm^{2}$ đặt trong từ trường đều cảm ứng từ $ B=0,1T$. Mặt phẳng vòng dây làm thành với từ trường một góc $\\alpha=30^{0}$ α = 30°. Tính từ thông qua S.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Mặt phẳng vòng dây hợp với $\\vec B$ góc $30^\\circ$ nên góc giữa pháp tuyến và $\\vec B$ là $\\alpha=90^\\circ-30^\\circ=60^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">$\\Phi=BS\\cos\\alpha=0,1\\cdot5\\cdot10^{-4}\\cdot\\cos60^\\circ=2,5\\cdot10^{-5}$ Wb.</p>","options":["$3\\cdot10^{-4}Wb$.","$3\\cdot10^{-5}Wb$.","$4,5\\cdot10^{-5}Wb$.","$2,5\\cdot10^{-5}Wb$"],"answer":3}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khung dây hình tròn đặt trong từ trường đều có cảm ứng từ $B=0,06 T$ sao cho mặt phẳng khung dây vuông góc với các đường sức từ. Từ thông qua khung dây là $1,2\\cdot10^{-5}Wb$. Bán kính vòng dây gần giá trị nào nhất sau đây?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Mặt phẳng khung vuông góc với đường sức nên $\\alpha=0^\\circ$, $\\Phi=BS=B\\pi r^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$r=\\sqrt{\\dfrac{\\Phi}{\\pi B}}=\\sqrt{\\dfrac{1,2\\cdot10^{-5}}{\\pi\\cdot0,06}}\\approx 7,98\\cdot10^{-3}$ m $\\approx 8$ mm.</p>","options":["12 mm.","6 mm.","7 mm.","8 mm."],"answer":3}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khung dây phẳng giới hạn diện tích $S=5 cm^{2}$ gồm 20 vòng dây đặt trong từ trường đều có cảm ứng từ $ B=0,1 T$ sao cho mặt phẳng khung dây hợp với vectơ cảm ứng từ một góc $60^{0}$. Tính từ thông qua diện tích giới hạn bởi khung dây.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Mặt phẳng khung hợp với $\\vec B$ góc $60^\\circ$ nên góc giữa $\\vec n$ và $\\vec B$ là $\\alpha=30^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">Khung có $N=20$ vòng: $\\Phi=NBS\\cos\\alpha=20\\cdot0,1\\cdot5\\cdot10^{-4}\\cdot\\cos30^\\circ\\approx8,66\\cdot10^{-4}$ Wb.</p>","options":["$8,66\\cdot10^{-4} Wb$.","$5\\cdot10^{-4} Wb$.","$4,5\\cdot10^{-5} Wb$.","$2,5\\cdot10^{-5} Wb$."],"answer":0}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khung dây hình vuông cạnh 5 cm đặt trong từ trường đều có cảm ứng từ $B=8\\cdot10^{-4} T$. Từ thông qua hình vuông đó bằng $10^{-6} Wb$. Tính góc hợp giữa vectơ cảm ứng từ và vectơ pháp tuyến của hình vuông đó.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Diện tích $S=(0,05)^2=2,5\\cdot10^{-3}$ m$^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Phi=BS\\cos\\alpha$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow\\cos\\alpha=\\dfrac{10^{-6}}{8\\cdot10^{-4}\\cdot2,5\\cdot10^{-3}}=0,5$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\alpha=60^\\circ$.</p>","options":["$\\alpha=0^{0}$.","$\\alpha=30^{0}$.","$\\alpha=60^{0}$.","$\\alpha=90^{0}$."],"answer":2}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khung dây hình tam giác có cạnh dài 10 cm, đường cao của nó là 8 cm. Cả khung dây được đưa vào một từ trường đều, sao cho các đường sức vuông góc với khung dây, từ thông xuyên qua khung dây là $40 \\mu Wb$. Tìm độ lớn cảm ứng từ.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Diện tích tam giác: $S=\\dfrac12\\cdot0,1\\cdot0,08=4\\cdot10^{-3}$ m$^2$ (đường sức vuông góc khung nên $\\alpha=0^\\circ$).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$B=\\dfrac{\\Phi}{S}=\\dfrac{40\\cdot10^{-6}}{4\\cdot10^{-3}}=0,01$ T.</p>","options":["$0,01 T$.","$0,1 T$.","$10^{-4} T$.","$10^{-3} T$."],"answer":0}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khung dây hình chữ nhật kích thước $3cm\\times4cm$ đặt trong từ trường đều có cảm ứng từ $ B=5\\cdot10^{-4} T$. Vectơ cảm ứng từ hợp với mặt phẳng khung một góc 30°. Từ thông qua khung dây đó là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vectơ cảm ứng từ hợp với mặt phẳng khung góc $30^\\circ$ nên góc với pháp tuyến là $\\alpha=60^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">$S=0,03\\cdot0,04=1,2\\cdot10^{-3}$ m$^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Phi=BS\\cos\\alpha=5\\cdot10^{-4}\\cdot1,2\\cdot10^{-3}\\cdot0,5=3\\cdot10^{-7}$ Wb.</p>","options":["$1,5\\sqrt{3}.10^{-7}Wb$.","$1,5.10^{-7}Wb$.","$3.10^{-7}Wb$.","$2.10^{-7}Wb$."],"answer":2}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một hình vuông cạnh 5 cm, đặt trong từ trường đều có cảm ứng từ B = 4.10$^{-4}$ T. Từ thông qua diện tích hình vuông đó bằng $10^{-6} Wb$. Góc hợp giữa vectơ cảm ứng từ và vectơ pháp tuyến của hình vuông đó là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Diện tích $S=(0,05)^2=2,5\\cdot10^{-3}$ m$^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\cos\\alpha=\\dfrac{\\Phi}{BS}=\\dfrac{10^{-6}}{4\\cdot10^{-4}\\cdot2,5\\cdot10^{-3}}=1$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\alpha=0^\\circ$.</p>","options":["$\\alpha=0^{0}$.","$\\alpha=30^{0}$.","$\\alpha=60^{0}$.","$\\alpha=90^{0}$."],"answer":0}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật Faraday và định luật Lenz","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vòng dây dẫn kín, phẳng được đặt trong từ trường đều. Trong khoảng thời gian $0,04 s,$ từ thông qua vòng dây giảm đều từ giá trị $6.10^{-3}Wb$ về 0 thì suất điện động cảm ứng xuất hiện trong vòng dây có độ lớn là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Độ lớn suất điện động cảm ứng: $|e_c|=\\left|\\dfrac{\\Delta\\Phi}{\\Delta t}\\right|$.</p><p class=\"text-base leading-relaxed my-2\">$|e_c|=\\dfrac{6\\cdot10^{-3}}{0,04}=0,15$ V.</p>","options":["$0,12 V.$","$0,15 V.$","$0,30 V.$","$0,24 V.$"],"answer":1}$q$::jsonb, 218, $q$Định luật Faraday và định luật Lenz$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật Faraday và định luật Lenz","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cuộn dây có N = 100 vòng, mỗi vòng có diện tích S = 300 cm$^{2}$. Đặt trong từ trường đều có cảm ứng từ B = 0,2 T sao cho trục của cuộn dây song song với các đường sức từ. Quay đều cuộn dây để sau ∆t = 0,5 s trục của nó vuông góc với các đường sức từ thì suất điện động cảm ứng trong cuộn dây có độ lớn là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Suất điện động cảm ứng trong cuộn dây có $N$ vòng: $|e|=N\\dfrac{|\\Delta\\Phi|}{\\Delta t}$.</p><p class=\"text-base leading-relaxed my-2\">Ban đầu trục cuộn dây song song đường sức từ nên pháp tuyến song song $\\vec B$: $\\Phi_1=BS=0,2\\cdot 0,03=6\\cdot10^{-3}$ Wb.</p><p class=\"text-base leading-relaxed my-2\">Sau đó trục vuông góc đường sức từ nên $\\Phi_2=0$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow |\\Delta\\Phi|=6\\cdot10^{-3}$ Wb</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow |e|=100\\cdot\\dfrac{6\\cdot10^{-3}}{0,5}=1,2$ V. Chọn B.</p>","options":["0,6 V.","1,2 V.","3,6 V.","4,8 V."],"answer":1}$q$::jsonb, 218, $q$Định luật Faraday và định luật Lenz$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật Faraday và định luật Lenz","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vòng dây dẫn hình vuông, cạnh $a=10 cm$, đặt cố định trong một từ trường đều có vectơ cảm ứng từ vuông góc với mặt khung. Trong khoảng thời gian $0,05 s$, cho độ lớn của cảm ứng từ tăng đều từ 0 đến $0,5 T$. Xác định độ lớn của suất điện động cảm ứng xuất hiện trong vòng dây.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ trường vuông góc mặt khung nên $\\Phi=BS$, $S=a^2=0,01$ m$^2$; $|e|=\\dfrac{S\\,\\Delta B}{\\Delta t}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow |e|=\\dfrac{0,01\\cdot0,5}{0,05}=0,1$ V. Chọn B.</p>","options":["$100\\left( V \\right).$","$0,1\\left( V \\right).$","$1,5\\left( V \\right).$","$0,15\\left( V \\right).$"],"answer":1}$q$::jsonb, 218, $q$Định luật Faraday và định luật Lenz$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ thông qua khung dây","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khung dây phẳng diện tích $20 cm^{2}$, gồm 10 vòng được đặt trong từ trường đều. Vectơ cảm ứng từ làm thành với mặt phẳng khung dây góc $30{^\\circ}$ và có độ lớn bằng $2.10^{-4}T.$ Người ta làm cho từ trường giảm đều đến 0 trong thời gian $0,01 s$ thì độ lớn suất điện động cảm ứng xuất hiện trong khung dây trong thời gian từ trường biến đổi.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Góc giữa $\\vec B$ và mặt phẳng khung là $30^\\circ$ nên góc giữa $\\vec B$ và pháp tuyến là $60^\\circ$: $\\Phi=BS\\cos60^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">$\\Phi_1=2\\cdot10^{-4}\\cdot20\\cdot10^{-4}\\cdot0,5=2\\cdot10^{-7}$ Wb, $\\Phi_2=0$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow |e|=N\\dfrac{|\\Delta\\Phi|}{\\Delta t}=10\\cdot\\dfrac{2\\cdot10^{-7}}{0,01}=2\\cdot10^{-4}$ V $=200\\ \\mu$V. Chọn A.</p><p class=\"text-base leading-relaxed my-2\">Phương án B, C nhầm giữa $\\cos30^\\circ$ và $\\sin30^\\circ$ (góc với mặt phẳng, không phải với pháp tuyến).</p>","options":["$200 \\left( \\mu V \\right).$","$180 \\left( \\mu V \\right).$","$160 \\left( \\mu V \\right).$","$80 \\left( \\mu V \\right).$"],"answer":0}$q$::jsonb, 217, $q$Từ thông qua khung dây$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật Faraday và định luật Lenz","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khung dây dẫn hình chữ nhật có diện tích $200 cm^{2}$, ban đầu ở vị trí song song với các đường sức từ của một từ trường đều có độ lướn $ B=0,01 T$. Khung quay đều trong thời gian $\\Delta t=0,04 s$ đến vị trí vuông góc với các đường sức từ. Độ lớn suất điện động cảm ứng xuất hiện trong khung là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khung (1 vòng) ban đầu song song đường sức từ nên $\\Phi_1=0$; sau khi quay vuông góc đường sức từ nên $\\Phi_2=BS=0,01\\cdot0,02=2\\cdot10^{-4}$ Wb.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow |e|=\\dfrac{|\\Delta\\Phi|}{\\Delta t}=\\dfrac{2\\cdot10^{-4}}{0,04}=5\\cdot10^{-3}$ V $=5$ mV. Chọn A.</p>","options":["$5 mV.$","$12 mV.$","$3,6 V.$","$4,8 V.$"],"answer":0}$q$::jsonb, 218, $q$Định luật Faraday và định luật Lenz$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật Faraday và định luật Lenz","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khung dây dẫn đặt vuông góc với một từ trường đều, cảm ứng từ B có độ lớn biến đổi theo thời gian. Biết rằng cường độ dòng điện cảm ứng là $0,5 A$, điện trở của khung là $ R=2 \\Omega$ và diện tích của khung là $ S=100 cm^{2}$. Tốc độ biến thiên của cảm ứng từ là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Dòng điện cảm ứng: $|e|=IR=0,5\\cdot2=1$ V.</p><p class=\"text-base leading-relaxed my-2\">Từ trường vuông góc khung: $|e|=S\\left|\\dfrac{\\Delta B}{\\Delta t}\\right|$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\left|\\dfrac{\\Delta B}{\\Delta t}\\right|=\\dfrac{1}{100\\cdot10^{-4}}=100$ T/s. Chọn C.</p>","options":["$200 \\left( T/s \\right).$","$180 \\left( T/s \\right).$","$100 \\left( T/s \\right).$","$80 \\left( T/s \\right).$"],"answer":2}$q$::jsonb, 218, $q$Định luật Faraday và định luật Lenz$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật Faraday và định luật Lenz","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một ống dây hình trụ dài gồm 1000 vòng dây, diện tích mỗi vòng dây $S=100 cm^{2}$. Ống dây có điện trở $ R=16 \\Omega$, hai đầu nối đoản mạch và được đặt trong từ trường đều có vectơ cảm ứng từ song song với trục của ống dây và có độ lớn tăng đều $10^{-2} T/s.$ Công suất tỏa nhiệt của ống dây là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ trường song song trục ống dây nên $|e|=NS\\left|\\dfrac{\\Delta B}{\\Delta t}\\right|=1000\\cdot10^{-2}\\cdot10^{-2}=0,1$ V.</p><p class=\"text-base leading-relaxed my-2\">Ống dây đoản mạch: $P=\\dfrac{e^2}{R}=\\dfrac{0,1^2}{16}=6,25\\cdot10^{-4}$ W $=625\\ \\mu$W. Chọn D.</p>","options":["$200\\left( \\mu W \\right).$","$680\\left( \\mu W \\right).$","$1000\\left( \\mu W \\right).$","$625\\left( \\mu W \\right).$"],"answer":3}$q$::jsonb, 218, $q$Định luật Faraday và định luật Lenz$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật Faraday và định luật Lenz","difficulty":"kho","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khung dây gồm 1000 vòng, mỗi vòng có diện tích là 80 cm². Khung dây được đặt trong từ trường đều sao cho vector cảm ứng từ vuông góc với vector đơn vị pháp tuyến của mặt phẳng vòng dây. Độ lớn cảm ứng từ là 0,8 T. Quay khung dây quanh trục quay vuông góc với vector cảm ứng từ thì trong khung dây xuất hiện suất điện động cảm ứng trung bình có độ lớn 6,4 V. Sau khoảng thời gian 1 s tính từ lúc khung dây bắt đầu quay, góc hợp bởi vector cảm ứng từ và mặt phẳng khung dây có thể nhận giá trị nào dưới đây?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Ban đầu $\\vec B\\perp$ pháp tuyến nên $\\Phi_1=0$. Suất điện động trung bình: $|e|=N\\dfrac{|\\Delta\\Phi|}{\\Delta t}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow |\\Delta\\Phi|=\\dfrac{6,4\\cdot1}{1000}=6,4\\cdot10^{-3}$ Wb.</p><p class=\"text-base leading-relaxed my-2\">Mà $BS=0,8\\cdot80\\cdot10^{-4}=6,4\\cdot10^{-3}$ Wb nên từ thông cực đại: $|\\Phi_2|=BS$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ pháp tuyến song song $\\vec B$, tức $\\vec B$ vuông góc mặt phẳng khung, góc giữa $\\vec B$ và mặt phẳng khung là $90^\\circ$. Chọn A.</p>","options":["90°.","0°.","30°.","45°."],"answer":0}$q$::jsonb, 218, $q$Định luật Faraday và định luật Lenz$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Giá trị hiệu dụng của dòng điện xoay chiều","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Điện áp hiệu dụng U và điện áp cực đại $U_{0}$ ở hai đầu một đoạn mạch xoay chiều liên hệ với nhau theo công thức</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Với dòng/điện áp xoay chiều hình sin, giá trị hiệu dụng bằng giá trị cực đại chia $\\sqrt2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow U=\\dfrac{U_0}{\\sqrt2}$. Chọn B.</p>","options":["$U = 2U_{0}.$","$U = \\frac{U_{0}}{\\sqrt{2}}.$","$U = \\frac{U_{0}}{2}.$","$U = U_{0}\\sqrt{2}.$"],"answer":1}$q$::jsonb, 219, $q$Giá trị hiệu dụng của dòng điện xoay chiều$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Viết biểu thức u, i theo thời gian","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Dòng điện xoay chiều trong một đoạn mạch có cường độ là i = $I_{0}$cos(ωt + φ) (ω $\\gt$ 0). Đại lượng ω được gọi là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong $i=I_0\\cos(\\omega t+\\varphi)$: $\\omega$ là tần số góc, $I_0$ là cường độ cực đại, $(\\omega t+\\varphi)$ là pha, $\\varphi$ là pha ban đầu. Chọn A.</p>","options":["tần số góc của dòng điện","cường độ dòng điện cực đại","pha của dòng điện","chu kỳ của dòng điện"],"answer":0}$q$::jsonb, 220, $q$Viết biểu thức u, i theo thời gian$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Viết biểu thức u, i theo thời gian","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Dòng điện xoay chiều qua một đoạn mạch có cường độ $i=4cos\\frac{2\\pi}{T}t (A) (T>0)$. Đại lượng T được gọi là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Viết $\\dfrac{2\\pi}{T}=\\omega$ với $\\omega=2\\pi/T$ nên $T$ là chu kì của dòng điện. Chọn B.</p>","options":["tần số góc của dòng điện.","chu kì của dòng điện.","tần số của dòng điện.","pha ban đầu của dòng điện."],"answer":1}$q$::jsonb, 220, $q$Viết biểu thức u, i theo thời gian$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Viết biểu thức u, i theo thời gian","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho dòng điện điện xoay chiều $i = 2cos\\left( 50\\pi t + \\frac{\\pi}{4} \\right)(A)$. Tại thời điểm t thì pha của cường độ dòng điện là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Pha của cường độ dòng điện tại thời điểm $t$ là đối số của hàm cosin: $50\\pi t+\\dfrac{\\pi}{4}$. Chọn D.</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{\\pi}{4}$ chỉ là pha ban đầu.</p>","options":["$50\\pi t$.","$\\frac{\\pi}{4}$.","$0$.","$50\\pi t + \\frac{\\pi}{4}$."],"answer":3}$q$::jsonb, 220, $q$Viết biểu thức u, i theo thời gian$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Giá trị hiệu dụng của dòng điện xoay chiều","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cường độ dòng điện trong mạch không phân nhánh có dạng $i=2\\sqrt{2}cos\\left( 100\\pi t \\right)V$. Cường độ dòng điện hiệu dụng trong mạch là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đề ghi đơn vị \"V\" là in nhầm, đại lượng là cường độ dòng điện (A).</p><p class=\"text-base leading-relaxed my-2\">$I=\\dfrac{I_0}{\\sqrt2}=\\dfrac{2\\sqrt2}{\\sqrt2}=2$ A. Chọn C.</p>","options":["$I=4A.$","$I=2,83A.$","$I=2A.$","$I=1,41A$"],"answer":2}$q$::jsonb, 219, $q$Giá trị hiệu dụng của dòng điện xoay chiều$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Giá trị hiệu dụng của dòng điện xoay chiều","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Điện áp tức thời giưa hai đầu đoạn mạch có dạng $u=141cos\\left( 100\\pi t \\right)V.$ Điện áp hiệu dụng hai đầu đoạn mạch là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$U=\\dfrac{U_0}{\\sqrt2}=\\dfrac{141}{\\sqrt2}\\approx100$ V. Chọn C.</p><p class=\"text-base leading-relaxed my-2\">Đáp án 141 V là điện áp cực đại, không phải hiệu dụng.</p>","options":["$U=141V.$","$U=50V.$","$U=100V.$","$U=200V.$"],"answer":2}$q$::jsonb, 219, $q$Giá trị hiệu dụng của dòng điện xoay chiều$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Viết biểu thức u, i theo thời gian","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một dòng điện xoay chiều chạy trong một động cơ điện có biểu thức $i=2cos\\left( 100\\pi t+\\frac{\\pi}{2} \\right)\\left( A \\right)$ (trong đó t tính bằng giây) thì</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$i=2\\cos(100\\pi t+\\pi/2)$ (A) có $I_0=2$ A, $\\omega=100\\pi$ rad/s.</p><p class=\"text-base leading-relaxed my-2\">A sai: $I=I_0/\\sqrt2=\\sqrt2$ A. B sai: không biết pha của điện áp nên không kết luận được độ lệch pha. D sai: $f=\\omega/2\\pi=50$ Hz ($100\\pi$ là tần số góc).</p><p class=\"text-base leading-relaxed my-2\">C đúng: $T=\\dfrac{2\\pi}{\\omega}=0,02$ s. Chọn C.</p>","options":["giá trị hiệu dụng của cường độ dòng điện I bằng 2A.","cường độ dòng điện i luôn sớm pha $\\frac{\\pi}{2}$ so với điện áp xoay chiều mà động cơ này sử dụng.","chu kì dòng điện bằng 0,02 s.","tần số dòng điện bằng $100\\pi$ Hz."],"answer":2}$q$::jsonb, 220, $q$Viết biểu thức u, i theo thời gian$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Viết biểu thức u, i theo thời gian","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một dòng điện chạy trong một đoạn mạch có cường độ i = 4cos(2πft + π/2) (A) (f $\\gt$ 0). Đại lượng f được gọi là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong $i=4\\cos(2\\pi ft+\\pi/2)$ ta có $\\omega=2\\pi f$ nên $f$ là tần số của dòng điện. Chọn B.</p>","options":["pha ban đầu của dòng điện.","tần số của dòng điện.","tần số góc của dòng điện.","chu kì của dòng điện."],"answer":1}$q$::jsonb, 220, $q$Viết biểu thức u, i theo thời gian$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Viết biểu thức u, i theo thời gian","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Điện áp $u=120cos\\left( 100\\pi t+\\frac{\\pi}{12} \\right)(V)$ có giá trị cực đại là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ $u=120\\cos(100\\pi t+\\pi/12)$ (V), điện áp cực đại là biên độ $U_0=120$ V. Chọn B.</p><p class=\"text-base leading-relaxed my-2\">Phương án $60\\sqrt2$ V ứng với giá trị hiệu dụng khi $U_0=120\\sqrt2$, không áp dụng ở đây; $120\\sqrt2$ V sai vì nhầm với $U_0=U\\sqrt2$.</p>","options":["60$\\sqrt{2}$ V.","120 V.","120$\\sqrt{2}$ V.","60V"],"answer":1}$q$::jsonb, 220, $q$Viết biểu thức u, i theo thời gian$q$)) as v(q, tid, tname)
