from (values ($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật Faraday và định luật Lenz","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khung dây phẳng quay đều với tốc độ $\\omega$ quanh trục cố định nằm trong mặt phẳng khung dây, trong một từ trường đều có vecto cảm ứng từ vuông góc với trục quay của khung. Suất điện động cảm ứng trong khung có biểu thức $ e=E_{0}cos\\omega t$. Biểu thức từ thông gửi qua khung dây là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$e$ chậm pha $\\frac{\\pi}{2}$ so với $\\Phi$, nên $\\Phi$ sớm pha $\\frac{\\pi}{2}$ so với $e$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\Phi=\\Phi_0\\cos(\\omega t+\\frac{\\pi}{2})$ với $\\Phi_0=\\frac{E_0}{\\omega}$.</p>","options":["$\\Phi=\\frac{E_{0}}{\\omega}\\cdot cos\\left( \\omega t-\\frac{\\pi}{2} \\right) \\left( Wb \\right)$","$\\Phi=\\omega E_{0}\\cdot cos\\left( \\omega t-\\frac{\\pi}{2} \\right) \\left( Wb \\right)$","$\\Phi=\\omega E_{0}\\cdot cos\\left( \\omega t+\\frac{\\pi}{2} \\right) \\left( Wb \\right)$","$\\Phi=\\frac{E_{0}}{\\omega}\\cdot cos\\left( \\omega t+\\frac{\\pi}{2} \\right) \\left( Wb \\right)$"],"answer":3}$q$::jsonb, 218, $q$Định luật Faraday và định luật Lenz$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật Faraday và định luật Lenz","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Từ thông qua một khung dây dẫn có biểu thức: $\\Phi=\\frac{2\\cdot10^{-2}}{\\pi}\\cdot cos\\left( 100\\pi t+\\frac{\\pi}{4} \\right) \\left( Wb \\right)$. Biểu thức suất điện động cảm ứng xuất hiện trong vòng dây này là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$E_0=\\omega\\Phi_0=100\\pi\\cdot\\frac{2\\cdot10^{-2}}{\\pi}=2$ V.</p><p class=\"text-base leading-relaxed my-2\">$e$ chậm pha $\\frac{\\pi}{2}$ so với $\\Phi$: $\\varphi_e=\\frac{\\pi}{4}-\\frac{\\pi}{2}=-\\frac{\\pi}{4}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$e=2\\cos(100\\pi t-\\frac{\\pi}{4})$ V.</p>","options":["$e=2\\cdot cos\\left( 100\\pi t+\\frac{\\pi}{4} \\right)\\left( V \\right)$","$e=2\\cdot cos\\left( 100\\pi t+\\frac{\\pi}{2} \\right)\\left( V \\right)$","$e=2\\cdot cos\\left( 100\\pi t-\\frac{\\pi}{4} \\right)\\left( V \\right)$","$e=2\\cdot cos\\left( 100\\pi t \\right)\\left( V \\right)$"],"answer":2}$q$::jsonb, 218, $q$Định luật Faraday và định luật Lenz$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nguyên tắc tạo ra dòng điện xoay chiều","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi nói về máy phát điện xoay chiều, điều nào sau đây là <strong>không đúng</strong> ?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phần cảm tạo từ trường, phần ứng tạo suất điện động; phần đứng yên là stato, phần quay là roto.</p><p class=\"text-base leading-relaxed my-2\">Phần cảm có thể là roto (máy có nam châm quay) hoặc stato nên phát biểu A (phần cảm luôn là stato, phần ứng luôn là roto) là không đúng.</p>","options":["Phần cảm gọi là Stato; phần ứng gọi là roto","Phần đứng yên gọi là stato, phần chuyển động gọi là roto.","Cấu tạo bởi hai bộ phận chính: phần cảm và phần ứng.","Phần cảm tạo ra từ trường, phần ứng tạo ra suất điện động cảm ứng"],"answer":0}$q$::jsonb, 236, $q$Nguyên tắc tạo ra dòng điện xoay chiều$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Điện từ trường và sóng điện từ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Ở Đài Tiếng nói Việt Nam, một máy đang phát sóng điện từ. Vào thời điểm t tại một điểm xác định ở phương truyền hướng thẳng đứng hướng lên trên, nếu cảm ứng từ đang có độ lớn cực đại và hướng về phía Nam thì cường độ điện trường có</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Sóng điện từ truyền theo $\\vec v$ với $\\vec E$, $\\vec B$ vuông góc nhau và cùng pha, $(\\vec E,\\vec B,\\vec v)$ tạo thành tam diện thuận.</p><p class=\"text-base leading-relaxed my-2\">Chọn Đông là $x$, Bắc là $y$, lên trên là $z$; $\\vec B$ hướng Nam ($-y$) và cực đại nên $\\vec E$ cũng cực đại.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\vec E\\times\\vec B$ cùng chiều $z$ nên $\\vec E$ hướng $-x$, tức hướng về phía Tây.</p>","options":["độ lớn cực đại và hướng về phía Đông.","độ lớn cực đại và hướng về phía Tây.","Độ lớn bằng không.","độ lớn cực đại và hướng về phía Bắc."],"answer":1}$q$::jsonb, 237, $q$Điện từ trường và sóng điện từ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Máy biến áp","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cuộn sơ cấp và cuộn thứ cấp của môt máy biến áp lí tưởng có số vòng dây lần lượt là $N_{1}$ và $ N_{2}$. Đặt điện áp xoay chiều có giá trị hiệu dụng $ U_{1}$ vào hai đầu cuộn sơ cấp thì điện áp hiệu dụng giữa hai đầu cuộn thứ cấp để hở là $ U_{2}$. Hệ thức đúng là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Máy biến áp lí tưởng: $\\frac{U_1}{U_2}=\\frac{N_1}{N_2}$ (cuộn thứ cấp để hở).</p>","options":["$\\frac{U_{1}}{U_{2}}=\\frac{N_{2}}{N_{1}}$.","$\\frac{U_{1}}{U_{2}}=\\frac{N_{1}}{+}N_{2}N_{1}$.","$\\frac{U_{1}}{U_{2}}=\\frac{N_{1}}{N_{2}}$.","$\\frac{U_{1}}{U_{2}}=\\frac{N_{1}}{+}N_{2}N_{2}$."],"answer":2}$q$::jsonb, 238, $q$Máy biến áp$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Máy biến áp","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Để giảm bớt hao phí do toả nhiệt trên đường dây khi cần tải điện năng đi xa bằng dòng điện xoay chiều, có thể dùng biện pháp</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Công suất hao phí $\\Delta P=\\frac{P^2R}{U^2}$, tăng $U$ lên $n$ lần thì $\\Delta P$ giảm $n^2$ lần nên A đúng.</p><p class=\"text-base leading-relaxed my-2\">B không phải biện pháp kĩ thuật thực tế chung; C sai vì giảm hiệu điện thế làm tăng dòng và hao phí; D không khả thi.</p>","options":["tăng hiệu điện thế ở nơi sản xuất điện lên n lần để giảm hao phí do toả nhiệt trên đường dây n² lần.","xây dựng nhà máy gần nơi tiêu thụ điện để giảm chiều dài đường dây truyền tải điện.","giảm hiệu điện thế máy phát điện n lần để giảm cường độ dòng điện trên dây n lần, giảm công suất toả nhiệt xuống n² lần.","dùng dây dẫn bằng vật liệu siêu dẫn có đường kính lớn."],"answer":0}$q$::jsonb, 238, $q$Máy biến áp$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Máy biến áp","difficulty":"kho","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một máy biết áp lí tưởng có hiệu suất bằng 1 được nối với nguồn xoay chiều có điện áp hiệu dụng 5 V. Biết số vòng dây của cuộn sơ cấp và thứ cấp lần lượt là 100 vòng và 150 vòng. Do ở cuộn sơ cấp có 10 vòng dây bị quấn ngược nên điện áp thu được ở cuộn thứ cấp là:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Cuộn sơ cấp 100 vòng có 10 vòng quấn ngược nên số vòng hiệu dụng là $100-2\\cdot10=80$ vòng.</p><p class=\"text-base leading-relaxed my-2\">$\\frac{U_2}{U_1}=\\frac{N_2}{N_1'}$ nên $U_2=5\\cdot\\frac{150}{80}=9{,}375\\approx9{,}37$ V.</p>","options":["9,37 V.","8,33 V.","7,5 V.","7,78 V."],"answer":0}$q$::jsonb, 238, $q$Máy biến áp$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính lực từ F = BIl·sinθ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một đoạn dây dẫn đặt trong một từ trường đều có cảm ứng từ 0,35 T. Khi dòng điện cường độ 14,5 A chạy qua đoạn dây dẫn, thì đoạn dây dẫn này bị tác dụng một lực từ bằng 1,65 N. Biết hướng của dòng điện hợp với hướng của từ trường một góc$30{^\\circ}$. Tính độ dài của đoạn dây dẫn đặt trong từ trường.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$F=BIl\\sin\\alpha$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow l=\\dfrac{F}{BI\\sin\\alpha}$.</p><p class=\"text-base leading-relaxed my-2\">$l=\\dfrac{1{,}65}{0{,}35\\cdot 14{,}5\\cdot 0{,}5}\\approx 0{,}65$ m. Chọn <strong>C</strong>.</p>","options":["0,45 m.","0,25 m.","0,65 m.","0,75 m."],"answer":2}$q$::jsonb, 216, $q$Tính lực từ F = BIl·sinθ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"kho","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hai dây dẫn thẳng, rất dài, đặt song song, cách nhau 10 cm trong không khí, có hai dòng điện ngược chiều, có cường độ lần lượt là $I_{1}$ = 6 A; $I_{2}$ = 12 A chạy qua. Xác định độ lớn cảm ứng từ tổng hợp do hai dòng điện này gây ra tại điểm M cách dây dẫn mang dòng $I_{1}$ là 5 cm và cách dây dẫn mang dòng $I_{2}$ là 15 cm.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">M cách $I_1$ 5 cm và $I_2$ 15 cm, hai dây cách nhau 10 cm nên M nằm ngoài đoạn nối, gần $I_1$; hai dòng ngược chiều nên hai vectơ ngược hướng.</p><p class=\"text-base leading-relaxed my-2\">$B_1=2\\cdot10^{-7}\\dfrac{6}{0{,}05}=2{,}4\\cdot10^{-5}$ T; $B_2=2\\cdot10^{-7}\\dfrac{12}{0{,}15}=1{,}6\\cdot10^{-5}$ T.</p><p class=\"text-base leading-relaxed my-2\">$B=B_1-B_2=0{,}8\\cdot10^{-5}$ T. Chọn <strong>C</strong>.</p>","options":["$7,6.10^{-5}T$","$4,4.10^{-5}T$","$0,8.10^{-5}T$","$4,0.10^{-5}T$"],"answer":2}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Viết biểu thức u, i theo thời gian","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tại thời điểm t, điện áp $u=200\\sqrt{2}cos\\left( 100\\pi t-\\frac{\\pi}{2} \\right)$ (trong đó u tính bằng V, t tính bằng s) có giá trị bằng $100\\sqrt{2} V$ và đang giảm. Sau thời điểm đó $\\frac{1}{300}s$, điện áp này có giá trị là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$u=100\\sqrt{2}=\\frac{U_0}{2}$ ($U_0=200\\sqrt{2}$) và đang giảm nên pha hiện tại là $\\frac{\\pi}{3}$.</p><p class=\"text-base leading-relaxed my-2\">Sau $\\frac{1}{300}$ s pha tăng thêm $100\\pi\\cdot\\frac{1}{300}=\\frac{\\pi}{3}$, thành $\\frac{2\\pi}{3}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow u=200\\sqrt{2}\\cos\\frac{2\\pi}{3}=-100\\sqrt{2}$ V.</p>","options":["−100 V.","$100\\sqrt{3}V$","$-100\\sqrt{2}V$","200 V."],"answer":2}$q$::jsonb, 220, $q$Viết biểu thức u, i theo thời gian$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật Faraday và định luật Lenz","difficulty":"kho","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khung dây đẫn quay đều với tốc độ 150 vòng/phút quanh trục vuông góc với đường sức của một từ trường đều $B$. Từ thông cực đại gửi qua khung là $\\frac{10}{\\pi}\\left( Wb \\right)$. Chọn gốc thời gian $ t=0$ là lúc pháp tuyến $\\overset{\\rightarrow}{n}$ của khung dây có chiều trùng với chiều của vecto cảm ứng từ $\\overset{\\rightarrow}{B}$. Biểu thức suất điện động cảm ứng e xuất hiện trong khung dây</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$\\omega=2\\pi\\cdot\\frac{150}{60}=5\\pi$ rad/s; $E_0=\\omega\\Phi_0=5\\pi\\cdot\\frac{10}{\\pi}=50$ V.</p><p class=\"text-base leading-relaxed my-2\">Tại $t=0$ pháp tuyến trùng $\\vec B$ nên $\\Phi=\\Phi_0\\cos\\omega t$, suy ra $e=-\\Phi'=E_0\\sin\\omega t$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$e=50\\sin(5\\pi t)$ V.</p>","options":["$e=25\\sqrt{2}\\cdot sin\\left( 5\\pi t \\right)\\left( V \\right)$","$e=25\\sqrt{2}\\cdot cos\\left( 5\\pi t \\right)\\left( V \\right)$","$e=50\\cdot sin\\left( 5\\pi t \\right)\\left( V \\right)$","$e=50\\cdot cos\\left( 5\\pi t \\right)\\left( V \\right)$"],"answer":2}$q$::jsonb, 218, $q$Định luật Faraday và định luật Lenz$q$)) as v(q, tid, tname)
